// autoDesc returns the auto-generated descriptor for tool name, or nil.
func autoDesc(name string) *autoToolDesc {
	if d, ok := autoDescMap[name]; ok {
		return &d
	}
	return nil
}

// autoDescKeys returns all auto-generated tool names.
func autoDescKeys() []string {
	keys := make([]string, 0, len(autoDescMap))
	for k := range autoDescMap {
		keys = append(keys, k)
	}
	return keys
}
